JS='''document.querySelectorAll('[data-slides]').forEach(box=>{const slides=JSON.parse(box.dataset.slides);let n=0;const show=()=>{box.querySelector('.slide h3').textContent=slides[n][0];box.querySelector('.slide p').textContent=slides[n][1];box.querySelector('output').textContent=(n+1)+' / '+slides.length;};box.querySelector('[data-prev]').onclick=()=>{n=(n+slides.length-1)%slides.length;show()};box.querySelector('[data-next]').onclick=()=>{n=(n+1)%slides.length;show()};show()});document.querySelectorAll('.request').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();if(!f.reportValidity())return;let d=new FormData(f);let t='Olá, gostaria de uma avaliação para '+f.dataset.service+'\\nNome: '+d.get('nome')+'\\nEmpresa: '+d.get('empresa')+'\\nCidade: '+d.get('cidade')+'\\nDemanda: '+d.get('demanda');window.open('https://wa.me/5531973632725?text='+encodeURIComponent(t),'_blank','noopener,noreferrer')}));'''
